begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('8c100000-0000-4000-8000-000000000001','synthetic-records@example.test','{}'),('8c100000-0000-4000-8000-000000000002','synthetic-records-other@example.test','{}');
update profiles set is_active=true where id in ('8c100000-0000-4000-8000-000000000001','8c100000-0000-4000-8000-000000000002');
insert into user_roles(user_id,role) values('8c100000-0000-4000-8000-000000000001','STAFF'),('8c100000-0000-4000-8000-000000000002','STAFF');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"8c100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Records','+13035550143','synthetic-records@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic records dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other_pet',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic records sibling','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into data values('save',jsonb_build_object('pet_id',(select id from fx where k='pet'),'client_id',(select id from fx where k='client'),'direction','outgoing','subset','full','channel','EMAIL','recipient_kind','client','requester_name','Synthetic client','request_note','Synthetic request','requested_on','2026-10-10','due_on','2026-10-20','assigned_to',auth.uid()));
create function pg_temp.save_req(i uuid,a uuid,rev integer,v jsonb) returns jsonb language sql as $$select save_record_request(a,i,rev,v)$$;
insert into data select 'saved',pg_temp.save_req('8c200000-0000-4000-8000-000000000001','8c300000-0000-4000-8000-000000000001',null,(select v from data where k='save'));
select throws_ok($$select save_record_request(gen_random_uuid(),gen_random_uuid(),null,(select v||jsonb_build_object('client_id',gen_random_uuid()) from data where k='save'))$$,'42501','Patient does not belong to household','Request cannot attach another household to a known patient');
select throws_ok($$select save_record_request(gen_random_uuid(),gen_random_uuid(),null,(select v||jsonb_build_object('assigned_to',gen_random_uuid()) from data where k='save'))$$,'23514','Assignee must be active staff','Unknown or inactive assignee is rejected');
select is((select v#>>'{request,version}' from data where k='saved'),'1','New request starts at version one');
select is((select v#>>'{request,recipient}' from data where k='saved'),'synthetic-records@example.test','Client destination comes from authoritative household');
select is(pg_temp.save_req('8c200000-0000-4000-8000-000000000001','8c300000-0000-4000-8000-000000000001',null,(select v from data where k='save')),(select v from data where k='saved'),'Exact action recovers immutable receipt');
select throws_ok($$select pg_temp.save_req('8c200000-0000-4000-8000-000000000001','8c300000-0000-4000-8000-000000000001',null,(select v||'{"request_note":"changed"}' from data where k='save'))$$,'23505','Action identifier conflicts with saved work','Changed retry cannot reuse action UUID');
select throws_ok($$select pg_temp.save_req('8c200000-0000-4000-8000-000000000001',gen_random_uuid(),7,(select v from data where k='save'))$$,'PT409','Request changed; reload','Stale version rejects without losing original');
select throws_ok($$select record_request_inventory((select id from fx where k='pet'))$$,'42501',null,'API cannot call internal capture helper');
select throws_ok($$select * from record_requests$$,'42501',null,'API cannot directly read private operational tables');
select is(jsonb_array_length(list_record_requests('{}',null,1)->'items'),1,'Bounded queue returns persisted request');
select is(read_record_request('8c200000-0000-4000-8000-000000000001')#>>'{request,due_on}','2026-10-20','Calendar due date persists');
select is(jsonb_array_length(list_record_request_evidence('8c200000-0000-4000-8000-000000000001','history',0,1)->'items'),1,'Immutable request history is paged');
-- 101 source records must partition, never silently stop at discovery page one.
select record_patient_weight((select id from fx where k='pet'),10+i/100.0,'kg','2026-01-01'::date+i) from generate_series(1,101) i;
insert into data values('manifest_values',jsonb_build_object('manifest_id','8c400000-0000-4000-8000-000000000001','selection','{}'::jsonb,'review_note','Synthetic full chart review'));
insert into data select 'manifest',prepare_record_request_manifest('8c300000-0000-4000-8000-000000000002','8c200000-0000-4000-8000-000000000001',1,(select v from data where k='manifest_values'));
select is((select v->>'package_count' from data where k='manifest'),'2','101 dated weights split into two numbered packages');
reset role;
select is((select count(*)::integer from record_request_manifests m cross join lateral jsonb_each(m.inventory) n where m.id='8c400000-0000-4000-8000-000000000001' and n.value->>'family'='weight_ids'),101,'Frozen inventory covers every eligible dated weight');
select is((select sum(jsonb_array_length(p.selection->'weight_ids'))::integer from record_request_packages p where manifest_id='8c400000-0000-4000-8000-000000000001'),101,'Package union includes all weights exactly once');
select ok(not exists(select 1 from record_request_packages where manifest_id='8c400000-0000-4000-8000-000000000001' and jsonb_array_length(selection->'weight_ids')>100),'Every package respects family limit');
insert into record_release_policy(id,enabled,accepted_at,accepted_by,acceptance_reference,accepted_schema_version) values(true,true,now(),'8c100000-0000-4000-8000-000000000001','Synthetic local clinical review',13) on conflict(id) do update set enabled=true,accepted_at=now(),accepted_by=excluded.accepted_by,acceptance_reference=excluded.acceptance_reference,accepted_schema_version=13;
set local role authenticated;
insert into data select 'package',read_record_request_package('8c200000-0000-4000-8000-000000000001',(list_record_request_packages('8c200000-0000-4000-8000-000000000001','8c400000-0000-4000-8000-000000000001',0,1)#>>'{items,0,id}')::uuid);
select throws_ok($$select confirm_record_release((select (v->>'release_id')::uuid from data where k='package'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','synthetic-records@example.test',(select v->'selection' from data where k='package'),(select v#>'{preview,snapshot}' from data where k='package'),(select v#>>'{preview,source_hash}' from data where k='package'),true)$$,'42501','Numbered releases must be confirmed through their records request','Direct release RPC cannot bypass atomic package association');
insert into data select 'confirmed',confirm_record_request_package('8c300000-0000-4000-8000-000000000003','8c200000-0000-4000-8000-000000000001',2,jsonb_build_object('package_id',(select v->'id' from data where k='package'),'manifest_hash',(select v->'fingerprint' from data where k='manifest'),'attest_review',true,'attest_scope_expansion',false));
select is((select v#>>'{request,status}' from data where k='confirmed'),'preparing','One confirmed package does not make whole manifest ready');
select throws_ok($$select transition_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000001',3,'{"status":"fulfilled","review_note":"Synthetic attempt"}')$$,'23514','Every numbered package needs provider-confirmed delivery; preparation or acceptance is not delivery','Incomplete package set cannot invent fulfillment');
select transition_record_request('8c300000-0000-4000-8000-000000000004','8c200000-0000-4000-8000-000000000001',3,'{"status":"cancelled","review_note":"Synthetic cancellation"}');
select is((read_record_release((select (v->>'release_id')::uuid from data where k='package'))->>'eligible')::boolean,false,'Cancellation invalidates confirmed package disclosure');
select is(list_record_request_evidence('8c200000-0000-4000-8000-000000000001','history',0,1)#>>'{items,0,action,review_note}','Synthetic cancellation','Staff history displays the immutable transition reason');
select is((read_record_release((select (v->>'release_id')::uuid from data where k='package'))#>>'{package_context,package_count}'),'2','Historical release keeps numbered manifest context');
-- Third-party confirmation starts off even after authority is recorded.
insert into data values('third_save',(select v||'{"recipient_kind":"third_party","recipient_name":"Synthetic clinic","recipient_email":"synthetic-clinic@example.test","subset":"custom"}' from data where k='save'));
select pg_temp.save_req('8c200000-0000-4000-8000-000000000002',gen_random_uuid(),null,(select v from data where k='third_save'));
insert into data select 'third_manifest',prepare_record_request_manifest(gen_random_uuid(),'8c200000-0000-4000-8000-000000000002',1,jsonb_build_object('manifest_id','8c400000-0000-4000-8000-000000000002','selection',jsonb_build_object('weight_ids',jsonb_build_array((select v#>'{selection,weight_ids,0}' from data where k='package'))),'review_note','Synthetic exact third-party review'));
insert into data select 'third_package',read_record_request_package('8c200000-0000-4000-8000-000000000002',(list_record_request_packages('8c200000-0000-4000-8000-000000000002','8c400000-0000-4000-8000-000000000002',0,1)#>>'{items,0,id}')::uuid);
select authorize_record_request_recipient(gen_random_uuid(),'8c200000-0000-4000-8000-000000000002',2,jsonb_build_object('authorization_id','8c500000-0000-4000-8000-000000000001','manifest_hash',(select v->'fingerprint' from data where k='third_manifest'),'client_authority','Synthetic client authorized exact selected record','destination_verification','Synthetic independently verified clinic address','expires_on',(now() at time zone 'America/Denver')::date+3,'evidence_document_id',null,'evidence_document_version',null,'attest_client_authority',true,'attest_destination',true,'attest_source_scope',true));
create function pg_temp.confirm_third(a uuid) returns jsonb language sql as $$select confirm_record_request_package(a,'8c200000-0000-4000-8000-000000000002',3,jsonb_build_object('package_id',(select v->'id' from data where k='third_package'),'manifest_hash',(select v->'fingerprint' from data where k='third_manifest'),'attest_review',true,'attest_scope_expansion',false))$$;
select throws_ok($$select pg_temp.confirm_third(gen_random_uuid())$$,'42501','Current recipient authority and disclosure review required','No disclosure policy seeded or activated by migration');
reset role;
insert into record_request_disclosure_policy(id,enabled,accepted_at,reviewer,review_reference) values(true,true,now(),'Synthetic local reviewer','Synthetic local workflow acceptance');
set local role authenticated;
select lives_ok($$select pg_temp.confirm_third('8c300000-0000-4000-8000-000000000005')$$,'Exact authorized third-party package confirms after local commissioning');
select is(read_record_release((select (v->>'release_id')::uuid from data where k='third_package'))#>>'{release,snapshot,recipient,address}','synthetic-clinic@example.test','Exact third-party destination is frozen');
select revoke_record_request_authorization(gen_random_uuid(),'8c200000-0000-4000-8000-000000000002',4,'{"authorization_id":"8c500000-0000-4000-8000-000000000001","review_note":"Synthetic client revoked"}');
select is((read_record_release((select (v->>'release_id')::uuid from data where k='third_package'))->>'eligible')::boolean,false,'Revocation blocks future disclosure');
select lives_ok($$select pg_temp.confirm_third('8c300000-0000-4000-8000-000000000005')$$,'Unchanged original confirmation receipt remains recoverable after revocation');
select is(read_record_request('8c200000-0000-4000-8000-000000000002')#>>'{authorization,revoked}','true','Revocation is visible in staff request history');
-- Actual original receipt; incoming clinic text never grants outgoing authority.
select pg_temp.save_req('8c200000-0000-4000-8000-000000000003',gen_random_uuid(),null,(select v||'{"direction":"incoming","channel":null}' from data where k='save'));
select prepare_patient_document('8c600000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,'synthetic-original.pdf','application/pdf',100,'other','',null,'internal');
select throws_ok($$select receive_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000003',1,'{"documents":[{"id":"8c600000-0000-4000-8000-000000000001","version":1}],"review_note":"Synthetic review"}')$$,'PT409',null,'Pending file cannot count as received evidence');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"application/pdf"}' from patient_documents where id='8c600000-0000-4000-8000-000000000001';
select finalize_patient_document('8c600000-0000-4000-8000-000000000001');
reset role;
insert into data select 'doc_version',to_jsonb(version) from patient_documents where id='8c600000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select receive_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000003',1,'{"documents":[{"id":"8c600000-0000-4000-8000-000000000001","version":1}],"review_note":"Synthetic stale original"}')$$,'PT409','Original is missing, changed or belongs to another patient','Finalization version must match reviewed original');
select lives_ok($$select receive_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000003',1,jsonb_build_object('documents',jsonb_build_array(jsonb_build_object('id','8c600000-0000-4000-8000-000000000001','version',(select v from data where k='doc_version'))),'review_note','Synthetic original reviewed'))$$,'Same-patient actual finalized original records receipt');
select lives_ok($$select transition_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000003',2,'{"status":"fulfilled","review_note":"Synthetic originals verified"}')$$,'Incoming fulfillment verifies real evidence');
select is(jsonb_array_length(list_record_request_evidence('8c200000-0000-4000-8000-000000000003','receipts')->'items'),1,'Saved incoming receipt remains inspectable');
-- Later voiding cannot manufacture current receipt evidence or erase historical receipt.
select pg_temp.save_req('8c200000-0000-4000-8000-000000000006',gen_random_uuid(),null,(select v||'{"direction":"incoming","channel":null}' from data where k='save'));
select receive_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000006',1,jsonb_build_object('documents',jsonb_build_array(jsonb_build_object('id','8c600000-0000-4000-8000-000000000001','version',(select v from data where k='doc_version'))),'review_note','Synthetic second receipt'));
select void_patient_document('8c600000-0000-4000-8000-000000000001',(select v::text::integer from data where k='doc_version'),'Synthetic later original void');
select throws_ok($$select transition_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000006',2,'{"status":"fulfilled","review_note":"Synthetic stale receipt"}')$$,'PT409','Verify the actual received originals before fulfillment','Voided original blocks fulfillment of pending received request');
select is(list_record_request_evidence('8c200000-0000-4000-8000-000000000006','receipts')#>>'{items,0,current_available}','false','Historical receipt survives with current availability false');
select is(list_record_request_evidence('8c200000-0000-4000-8000-000000000006','receipts')#>>'{items,0,original,status}','ready','Original received metadata stays immutable after later void');
-- Ticket free text is informational; only an explicit patient/household association is authoritative.
insert into fx select 'other_client',id from save_client(auth.uid(),null,null,'Synthetic','Other records household','+13035550144','synthetic-other-records@example.test','EMAIL',null,null);
insert into fx select 'other_conversation',id from ensure_active_conversation((select id from fx where k='other_client'));
reset role;
insert into tickets(id,form_type,client_name,client_contact,pet_name) values('8c900000-0000-4000-8000-000000000001',(select enumlabel::ticket_form_type from pg_enum where enumtypid='ticket_form_type'::regtype order by enumsortorder limit 1),'Synthetic free-text clinic','not an authoritative client ID','Synthetic ambiguous pet');
insert into tickets(id,form_type,client_name,client_contact,pet_name,conversation_id) select '8c900000-0000-4000-8000-000000000002',form_type,'Synthetic other household','Synthetic contact','Synthetic other pet',(select id from fx where k='other_conversation') from tickets where id='8c900000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select pg_temp.save_req('8c200000-0000-4000-8000-000000000007',gen_random_uuid(),null,(select v||'{"ticket_id":"8c900000-0000-4000-8000-000000000001"}' from data where k='save'))$$,'Existing ticket links to explicitly selected authoritative patient');
select is(read_record_request('8c200000-0000-4000-8000-000000000007')#>>'{request,ticket_id}','8c900000-0000-4000-8000-000000000001','Ticket association persists');
select throws_ok($$select pg_temp.save_req(gen_random_uuid(),gen_random_uuid(),null,(select v||'{"ticket_id":"8c900000-0000-4000-8000-000000000002"}' from data where k='save'))$$,'42501','Ticket conversation belongs to another household','Ticket conversation cannot cross explicit household boundary');
-- Vaccine preset cannot accidentally disclose medication or broad chart history.
select record_patient_treatment('8c700000-0000-4000-8000-000000000001',jsonb_build_object('historical',true,'kind','vaccine','pet_id',(select id from fx where k='pet'),'quantity',1,'product_name','Synthetic vaccine','manufacturer','Synthetic','lot_number','SYNTHETIC','dose','Synthetic','route','Synthetic','veterinarian','Synthetic external veterinarian','administered_at',now()-interval '1 year','source','Synthetic historical vaccine'));
select record_patient_treatment('8c700000-0000-4000-8000-000000000002',jsonb_build_object('historical',true,'kind','medication','pet_id',(select id from fx where k='pet'),'quantity',1,'product_name','Synthetic medication','manufacturer','Synthetic','lot_number','SYNTHETIC','dose','Synthetic','route','Synthetic','veterinarian','Synthetic external veterinarian','administered_at',now()-interval '1 year','source','Synthetic historical medication'));
select pg_temp.save_req('8c200000-0000-4000-8000-000000000004',gen_random_uuid(),null,(select v||'{"subset":"vaccines"}' from data where k='save'));
select prepare_record_request_manifest(gen_random_uuid(),'8c200000-0000-4000-8000-000000000004',1,'{"manifest_id":"8c400000-0000-4000-8000-000000000004","selection":{},"review_note":"Synthetic vaccine-only review"}');
reset role;
select is((select source_count from record_request_manifests where id='8c400000-0000-4000-8000-000000000004'),1,'Vaccine preset includes exactly the eligible native vaccine');
select ok((select inventory ? 'treatment_ids:8c700000-0000-4000-8000-000000000001' and not inventory ? 'treatment_ids:8c700000-0000-4000-8000-000000000002' from record_request_manifests where id='8c400000-0000-4000-8000-000000000004'),'Medication stays out of vaccine package');
set local role authenticated;
-- Laboratory preset closes required originals and makes broader original scope explicit.
select prepare_patient_document('8c600000-0000-4000-8000-000000000002',(select id from fx where k='pet'),null,'synthetic-broad-original.pdf','application/pdf',100,'other','',null,'client_shareable');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"application/pdf"}' from patient_documents where id='8c600000-0000-4000-8000-000000000002';
select finalize_patient_document('8c600000-0000-4000-8000-000000000002');
select save_patient_lab_order('8c800000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,jsonb_build_object('test_name','Synthetic CBC','status','resulted','collected_date',(now() at time zone 'America/Denver')::date,'result_date',(now() at time zone 'America/Denver')::date,'result_document_id','8c600000-0000-4000-8000-000000000002'),'');
select pg_temp.save_req('8c200000-0000-4000-8000-000000000005',gen_random_uuid(),null,(select v||'{"subset":"labs"}' from data where k='save'));
select prepare_record_request_manifest(gen_random_uuid(),'8c200000-0000-4000-8000-000000000005',1,'{"manifest_id":"8c400000-0000-4000-8000-000000000005","selection":{},"review_note":"Synthetic laboratory scope"}');
reset role;
select is((select source_count from record_request_manifests where id='8c400000-0000-4000-8000-000000000005'),2,'Lab and its original form one complete dependency group');
select ok((select scope_expansion from record_request_packages where manifest_id='8c400000-0000-4000-8000-000000000005'),'Broader-than-lab original requires additional scope review');
select is((select package_count from record_request_manifests where id='8c400000-0000-4000-8000-000000000005'),1,'Required lab/original stay together');
set local role authenticated;
select throws_ok($$select confirm_record_request_package(gen_random_uuid(),'8c200000-0000-4000-8000-000000000005',2,jsonb_build_object('package_id',(list_record_request_packages('8c200000-0000-4000-8000-000000000005','8c400000-0000-4000-8000-000000000005')#>>'{items,0,id}'),'manifest_hash',(read_record_request('8c200000-0000-4000-8000-000000000005')#>>'{manifest,fingerprint}'),'attest_review',true,'attest_scope_expansion',false))$$,'23514','Review the additional required original/provenance disclosure','No broad original released without explicit expansion review');
-- A shared original connecting101 lab results may not be split or silently trimmed.
select save_patient_lab_order(gen_random_uuid(),(select id from fx where k='pet'),null,jsonb_build_object('test_name','Synthetic consolidated result '||i,'status','resulted','collected_date',(now() at time zone 'America/Denver')::date,'result_date',(now() at time zone 'America/Denver')::date,'result_document_id','8c600000-0000-4000-8000-000000000002'),'') from generate_series(1,100) i;
select throws_ok($$select prepare_record_request_manifest(gen_random_uuid(),'8c200000-0000-4000-8000-000000000005',2,'{"manifest_id":"8c400000-0000-4000-8000-000000000006","selection":{},"review_note":"Synthetic oversized shared-original graph"}')$$,'23514','A connected source/original group exceeds reviewed package capacity; no sources were omitted','Oversized dependency group fails explicitly without partial capture');
select is(read_record_request('8c200000-0000-4000-8000-000000000005')#>>'{manifest,id}','8c400000-0000-4000-8000-000000000005','Failed recapture leaves exact prior manifest intact');
select throws_ok($$select list_record_requests('{}',null,null)$$,'23514','Bounded queue filters required','Null page limit cannot disable queue bounds');
select throws_ok($$select transition_record_request(gen_random_uuid(),'8c200000-0000-4000-8000-000000000005',2,'{"status":"received","review_note":"Synthetic status checkbox"}')$$,'23514','Resume requires verified saved incoming originals','Outgoing status cannot fabricate received evidence');
reset role;
set local role service_role;
select throws_ok($$select list_record_requests()$$,'42501',null,'Service cannot make staff workflow decisions');
reset role;
set local role anon;
select throws_ok($$select list_record_requests()$$,'42501',null,'Anonymous cannot read staff request queue');
reset role;
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=false where id='8c100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"8c100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select list_record_requests()$$,'42501',null,'Offboarded actor cannot read workflow');
reset role;
select * from finish();rollback;
